CREATE TABLE IF NOT EXISTS production_stage_rows (id SERIAL PRIMARY KEY, award_id INTEGER NOT NULL REFERENCES awards(id) ON DELETE CASCADE, component_type VARCHAR(30) NOT NULL, stage_key VARCHAR(50) NOT NULL, status VARCHAR(200), stage_date DATE, attachment_note VARCHAR(500), UNIQUE (award_id, component_type, stage_key));
CREATE TABLE IF NOT EXISTS production_component_ready (id SERIAL PRIMARY KEY, award_id INTEGER NOT NULL REFERENCES awards(id) ON DELETE CASCADE, component_type VARCHAR(30) NOT NULL, is_ready BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE (award_id, component_type));
